import { erpUnitList } from "@/api/system/dept";
import { erpProjectType, erpRefresh } from '@/api/assets/projectManage';
export default {
  props: ['isShow'],
  data: function data() {
    return {
      submitForm: {
        projectCreateStartTime: ''
      },
      rules: {
        projectTypeCode: [{
          required: true,
          message: '项目类型不能为空',
          trigger: 'change'
        }],
        projectUnitCode: [{
          required: true,
          message: 'erp单位不能为空',
          trigger: 'change'
        }],
        projectCreateStartTime: [{
          required: true,
          message: '创建时间不能为空',
          trigger: 'change'
        }]
      },
      projecTypeList: [],
      erpUnits: [],
      projectTimes: [],
      btnLoading: false
    };
  },
  mounted: function mounted() {
    this.getDict();
  },
  methods: {
    // 字典
    getDict: function getDict() {
      var _this = this;
      erpUnitList().then(function (res) {
        _this.erpUnits = res.data;
      });
      erpProjectType({
        current: 1,
        size: 99999
      }).then(function (res) {
        _this.projecTypeList = res.data.records;
      });
    },
    changeTime: function changeTime(val) {
      if (val != null) {
        this.$set(this.submitForm, 'projectCreateStartTime', val[0]);
        // this.submitForm.projectCreateStartTime = val[0]
        this.submitForm.projectCreateEndTime = val[1];
      } else {
        this.submitForm.projectCreateStartTime = '';
        this.submitForm.projectCreateEndTime = '';
      }
    },
    // 刷新
    handleRefresh: function handleRefresh() {
      var _this2 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          _this2.btnLoading = true;
          erpRefresh(_this2.submitForm).then(function (res) {
            _this2.$message({
              type: "success",
              message: "刷新成功!"
            });
            _this2.btnLoading = false;
            _this2.$emit('submit');
          });
        }
      });
    }
  }
};
